using System;using System.Linq;using System.Collections.Generic;using System.Globalization;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;
public sealed class MiniSpark:FrameworkElement,IFrameMotion{
 public IList<ResourceSample> Data;List<double> from=new List<double>(),target=new List<double>();List<ResourceSample> samples=new List<ResourceSample>();double started,blend=1;readonly ToolTip tip=new ToolTip();int hover=-1;bool memory;
 public MiniSpark(bool useMemory=false){Width=78;Height=26;VerticalAlignment=VerticalAlignment.Center;memory=useMemory;MouseMove+=(s,e)=>{if(samples.Count==0)return;int i=Math.Max(0,Math.Min(samples.Count-1,(int)Math.Round(e.GetPosition(this).X/Math.Max(1,ActualWidth)*(samples.Count-1))));if(i==hover)return;hover=i;tip.Content=samples[i].Time.ToLocalTime().ToString("HH:mm:ss")+"  "+(memory?samples[i].Memory:samples[i].Cpu).ToString("0.0")+"%";tip.PlacementTarget=this;tip.IsOpen=true;};MouseLeave+=(s,e)=>{tip.IsOpen=false;hover=-1;};Unloaded+=(s,e)=>{MotionClock.Remove(this);tip.IsOpen=false;};}
 public void Refresh(){var next=(Data??new List<ResourceSample>()).Where(x=>!double.IsNaN(memory?x.Memory:x.Cpu)).TakeLastCompat(24).ToList();if(samples.Count==next.Count&&samples.Count>0&&samples.Last().Time==next.Last().Time)return;samples=next;from=target.ToList();target=next.Select(x=>memory?x.Memory:x.Cpu).ToList();if(from.Count!=target.Count)from=target.ToList();blend=IsLoaded&&IsVisible&&Motion.Enabled?0:1;started=MotionClock.Now;if(blend<1)MotionClock.Add(this);InvalidateVisual();}
 public bool Frame(double now){blend=Motion.Ease(Math.Min(1,(now-started)/.48));InvalidateVisual();return blend<1&&IsVisible&&IsLoaded;}
 protected override void OnRender(DrawingContext dc){if(target.Count<2){dc.DrawLine(new Pen(Theme.Line,1.4),new Point(0,Height/2),new Point(ActualWidth,Height/2));return;}var geo=new StreamGeometry();using(var c=geo.Open()){double cap=Math.Max(20,target.Max()*1.25);for(int i=0;i<target.Count;i++){double v=from[i]+(target[i]-from[i])*blend;var p=new Point(ActualWidth*i/(target.Count-1),ActualHeight-2-v/cap*(ActualHeight-4));if(i==0)c.BeginFigure(p,false,false);else c.LineTo(p,true,false);}}dc.DrawGeometry(null,new Pen(Theme.B("#A5B2D8"),1.5){LineJoin=PenLineJoin.Round},geo);}
}
public static class FooterSequence {public static IEnumerable<T> TakeLastCompat<T>(this IEnumerable<T> items,int count){var list=items.ToList();return list.Skip(Math.Max(0,list.Count-count));}}
public sealed class GpuMini:FrameworkElement,IFrameMotion{
 double[] start=new double[0],target=new double[0];double began,blend=1;public GpuMini(){Width=62;Height=24;VerticalAlignment=VerticalAlignment.Center;Unloaded+=(s,e)=>MotionClock.Remove(this);}
 public void Set(IEnumerable<Gpu> gpus){var next=gpus.Select(x=>GpuCard.Number(x.Util)).ToArray();start=target.Length==next.Length?target:next;target=next;blend=IsLoaded&&IsVisible&&Motion.Enabled?0:1;began=MotionClock.Now;if(blend<1)MotionClock.Add(this);InvalidateVisual();}
 public bool Frame(double now){blend=Motion.Ease(Math.Min(1,(now-began)/.46));InvalidateVisual();return blend<1&&IsVisible&&IsLoaded;}
 protected override void OnRender(DrawingContext dc){if(target.Length==0)return;double gap=Math.Min(3,ActualWidth/Math.Max(1,target.Length*3)),w=Math.Min(5,Math.Max(0,(ActualWidth-gap*(target.Length-1))/target.Length));for(int i=0;i<target.Length;i++){double value=start[i]+(target[i]-start[i])*blend,h=Math.Max(2,ActualHeight*value/100);dc.DrawRectangle(Theme.B("#9EA9D5"),null,new Rect(i*(w+gap),ActualHeight-h,w,h));}}
}
